 function canvasFont(size,score=false){return (score?'400 ':'400 ')+size+'px '+(score?(isTest()?'"Share Tech Mono"':'"Orbitron"'):(isTest()?'"Inter"':'"Russo One"'));}
 function drawPad(){const w=padSize.w,h=padSize.h,x=w*.5,y=h*.58,c=pc,compact=h<150;c.clearRect(0,0,w,h);const aim=gesture||aimPreview,alpha=gesture?.mode==='loft'?'#e6f9a5':'#c1d6cc';
  c.textAlign='center';c.font=canvasFont(12);const slots=[[0,-32],[.29,-21],[.39,10],[.29,compact?28:35],[-.29,-21],[-.35,10],[-.29,compact?28:35]],guide=Cricket.Strokes.guide(guideBall(),aim?.mode||(state.loftIntent?'loft':'ground')),spots=guide.map(o=>[o.label,...slots[o.slot],o.angle]);
  for(const [text,dx,dy,angle]of spots){const selected=aim&&Math.abs(aim.angle-angle)<22&&aim.mode!=='defend';c.fillStyle=selected?'#edffc4':'#9cb8b180';c.fillText(text,x+dx*w,y+dy);}
  c.strokeStyle='#77928966';c.lineWidth=1;c.beginPath();c.arc(x,y,20,0,Math.PI*2);c.stroke();c.beginPath();c.arc(x,y,5,0,Math.PI*2);c.stroke();
  if(aim){const rad=aim.angle*Math.PI/180,len=aim.mode==='defend'?8:aim.mode==='ground'?lerp(19,46,aim.effort??(gesture?Gesture.effort(gesture):.60)):52,xx=x+Math.sin(rad)*len,yy=y-Math.cos(rad)*len;c.strokeStyle=alpha;c.lineWidth=3;c.lineCap='round';c.beginPath();c.moveTo(x,y);c.lineTo(xx,yy);c.stroke();circle(c,xx,yy,4.5,alpha);if(gesture){c.strokeStyle='#bdd6a833';c.setLineDash([2,4]);c.beginPath();c.arc(x,y,52,0,Math.PI*2);c.stroke();c.setLineDash([]);}}
 }
 const Sound=(()=>{
  let context=null,master=null,enabled=true,pending=null,result=null,pitchHeard=false,previousTime=null,eventHeard=false,returnHeard=false,celebrationHeard=false;const buffers=new Map(),sources=new Set();
  try{enabled=localStorage.getItem('cricket.sound')!=='off';}catch{}
  function label(){const button=$('soundBtn');button.textContent=enabled?'Sound on':'Sound off';button.setAttribute('aria-pressed',String(enabled));button.setAttribute('aria-label',enabled?'Mute game sounds':'Enable game sounds');}
  function unlock(){if(!enabled||paused)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;if(!context){context=new Audio();master=context.createGain();master.gain.value=.50;master.connect(context.destination);}if(context.state==='suspended')context.resume().catch(()=>{});}catch{}}
  function play(kind,volume=1){if(!enabled||!context||context.state!=='running'||!kind)return;try{let buffer=buffers.get(kind);if(!buffer){const data=Cricket.SoundDesign.samples(kind,context.sampleRate);buffer=context.createBuffer(1,data.length,context.sampleRate);buffer.copyToChannel(data,0);buffers.set(kind,buffer);}const source=context.createBufferSource(),gain=context.createGain();source.buffer=buffer;gain.gain.value=clamp(volume,0,1);source.connect(gain);gain.connect(master);sources.add(source);source.onended=()=>{sources.delete(source);source.disconnect();gain.disconnect();};source.start();}catch{}}
  function toggle(){enabled=!enabled;try{localStorage.setItem('cricket.sound',enabled?'on':'off');}catch{}label();if(enabled&&!paused){unlock();play('middle',.55);}else suspend();}
  function suspend(){if(context)context.suspend().catch(()=>{});}
  function reset(){for(const source of sources)try{source.stop();}catch{}sources.clear();pending=null;result=null;previousTime=null;pitchHeard=false;eventHeard=false;returnHeard=false;celebrationHeard=false;}
  function tick(){if(paused||simulating)return;const b=state.pending;if(pending!==b){pending=b;pitchHeard=!b||state.elapsed>b.duration*b.bounceT;result=null;previousTime=null;eventHeard=false;returnHeard=false;celebrationHeard=false;}
   if(state.phase==='flight'&&b&&!pitchHeard&&state.elapsed>=b.duration*b.bounceT){pitchHeard=true;play('turf',.65);}
   const r=resultPhase()?lastResult():null;if(!r?.play)return;const t=playback(r);if(!result){previousTime=state.resultAge>300?t:0;eventHeard=state.resultAge>300&&t>=r.play.event.time;returnHeard=state.resultAge>300&&t>=(r.play.throw?.breakTime??Infinity);celebrationHeard=!!r.crowdHeard||state.resultAge>300&&t>=(r.decisionTime??r.play.event.time);}result=r;
   if(r.stumpsHitTime!==undefined&&r.stumpsHitTime>previousTime&&r.stumpsHitTime<=t)play('stumps',.65);
   for(const bounce of r.play.bounces||[])if(bounce.time>previousTime&&bounce.time<=t&&bounce.time<r.play.event.time)play('turf',clamp(bounce.impact/14,.15,.70));
   if(!eventHeard&&t>=r.play.event.time){eventHeard=true;const type=r.play.event.type;if(['catch','pickup','take'].includes(type))play('glove',type==='pickup'?.35:.8);if(type==='stumps')play('stumps');if(type==='lbw')play('bat',.25);}
   if(!returnHeard&&r.play.throw&&t>=r.play.throw.breakTime){returnHeard=true;play(r.dismissalKind==='runOut'?'stumps':'glove',.7);}
   if(!celebrationHeard&&t>=(r.decisionTime??r.play.event.time)){celebrationHeard=true;if(!r.crowdHeard){r.crowdHeard=true;const response=Cricket.Crowd.response(r.celebrations);if(response)play('crowd-'+response.kind);persist();}}previousTime=t;
  }
  return{unlock,play,toggle,tick,label,suspend,reset};
 })();

 function guideBall(){return state.pending||{...activeType(),archetype:activeType().id,scoringVersion:career()?17:4,battingHand:career()?Hand.of(state.match.batters[state.match.striker]):'right'};}
 function updateAim(){if(!gesture)return;aimPreview={angle:gesture.angle,mode:gesture.mode,effort:Gesture.effort(gesture)};const name=Shot.describe(gesture.angle,gesture.mode,guideBall()),strength=guideBall().scoringVersion>=8?Cricket.Strokes.strength(name,gesture.mode,aimPreview.effort):gesture.mode==='ground'&&career()?(aimPreview.effort<.45?'push':aimPreview.effort<.8?'firm ground stroke':'full ground stroke'):({defend:'soft hands',ground:'along the ground',loft:'lofted'}[gesture.mode]);$('padLabel').textContent=name+' · '+strength;if(state.phase==='flight'){$('feedbackTitle').textContent=name;$('feedbackDetail').textContent=strength;$('quality').textContent=guideBall().scoringVersion>=8&&['Late cut','Leg glance','Paddle sweep'].includes(name)?'GUIDED':gesture.mode.toUpperCase();$('quality').hidden=false;}renderTools();}
